package com.walletpay.controller; import com.walletpay.dto.*; import com.walletpay.service.WalletService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class WalletController {private final WalletService service; public WalletController(WalletService s){service=s;} private Long id(Authentication a){return (Long)a.getPrincipal();} @GetMapping("/user") public Map<String,Object> user(Authentication a){return Map.of("userId",id(a));} @GetMapping("/balance") public BalanceResponse balance(Authentication a){return service.balance(id(a));} @PostMapping("/onramp") public Map<String,String> onramp(Authentication a,@Valid @RequestBody AddMoneyRequest r){String token=service.createOnRamp(id(a),r);return Map.of("message","Done","token",token);} @PostMapping("/onramp/complete") public BalanceResponse completeOnramp(Authentication a,@Valid @RequestBody AddMoneyRequest r){service.addMoney(id(a),r);return service.balance(id(a));} @PostMapping("/p2p/transfer") public Map<String,String> transfer(Authentication a,@Valid @RequestBody SendMoneyRequest r){service.transfer(id(a),r);return Map.of("message","Transfer successful");} @GetMapping("/transactions") public List<TransactionResponse> transactions(Authentication a){return service.transactions(id(a));}}
